import { defineCollection, z } from "astro:content";
import { glob } from "astro/loaders";
import { docsLoader } from "@astrojs/starlight/loaders";
import { docsSchema } from "@astrojs/starlight/schema";

// ---------------------------------------------------------------------------
// Roadmap collection — structured (JSON) version of docs/roadmap.md.
// One entry per JSON file under src/content/roadmap/.
// The dashboard page consumes this; humans still read the rendered MDX page
// generated by scripts/sync-roadmap.mjs from the upstream markdown.
// ---------------------------------------------------------------------------

const statusEnum = z.enum(["shipped", "in-flight", "planned"]);

const itemSchema = z.object({
  id: z.string(),
  title: z.string(),
  description: z.string().optional(),
  phase: z.string().optional(),
  status: statusEnum.optional(),
});

const subphaseSchema = z.object({
  id: z.string(),
  title: z.string(),
  status: statusEnum,
  bullets: z.array(z.string()),
});

const sectionSchema = z.discriminatedUnion("kind", [
  z.object({
    id: z.string(),
    title: z.string(),
    kind: z.literal("items"),
    summary: z.string().optional(),
    items: z.array(itemSchema),
  }),
  z.object({
    id: z.string(),
    title: z.string(),
    kind: z.literal("subphases"),
    summary: z.string().optional(),
    subphases: z.array(subphaseSchema),
    architectureNote: z
      .object({
        title: z.string(),
        paragraphs: z.array(z.string()),
      })
      .optional(),
  }),
]);

const roadmap = defineCollection({
  loader: glob({ pattern: "*.json", base: "./src/content/roadmap" }),
  schema: z.object({
    $schema: z.string().optional(),
    version: z.string(),
    lastUpdated: z.string(),
    intro: z.string(),
    canonicalOrderNote: z.string().optional(),
    sections: z.array(sectionSchema),
  }),
});

// ---------------------------------------------------------------------------
// GitHub snapshot collection — built by scripts/fetch-github.mjs at predev /
// prebuild time. Single entry (`snapshot.json`). Gitignored.
// ---------------------------------------------------------------------------

const ghUser = z.object({
  login: z.string(),
  avatar_url: z.string().url().optional(),
  html_url: z.string().url().optional(),
});

const ghLabel = z.object({
  name: z.string(),
  color: z.string().optional(),
  description: z.string().nullable().optional(),
});

const ghIssueOrPR = z.object({
  number: z.number(),
  title: z.string(),
  state: z.string(),
  html_url: z.string().url(),
  user: ghUser.nullable().optional(),
  labels: z.array(ghLabel).default([]),
  created_at: z.string(),
  updated_at: z.string(),
  closed_at: z.string().nullable().optional(),
  merged_at: z.string().nullable().optional(),
  draft: z.boolean().optional(),
  comments: z.number().optional(),
});

const ghCommit = z.object({
  sha: z.string(),
  message: z.string(),
  author: z.string().nullable().optional(),
  date: z.string(),
  url: z.string().url(),
  // Branch the commit was discovered on. Default-branch commits carry
  // the repo's default branch name; feat/* etc. carry their own. Added
  // 2026-05-30 to surface the real activity on the engineering dashboard
  // (the default /commits endpoint only sees main).
  branch: z.string().optional(),
});

const ghBranch = z.object({
  name: z.string(),
  sha: z.string().nullable().optional(),
  protected: z.boolean().optional(),
  recent_commits: z.number().default(0),
  is_default: z.boolean().default(false),
});

const ghRelease = z.object({
  tag_name: z.string(),
  name: z.string().nullable().optional(),
  html_url: z.string().url(),
  published_at: z.string().nullable().optional(),
  prerelease: z.boolean().optional(),
  draft: z.boolean().optional(),
});

const github = defineCollection({
  loader: glob({ pattern: "*.json", base: "./src/content/github" }),
  schema: z.object({
    fetchedAt: z.string(),
    repo: z.object({
      full_name: z.string(),
      description: z.string().nullable().optional(),
      html_url: z.string().url(),
      homepage: z.string().nullable().optional(),
      default_branch: z.string(),
      visibility: z.string(),
      stargazers_count: z.number(),
      watchers_count: z.number(),
      forks_count: z.number(),
      open_issues_count: z.number(),
      subscribers_count: z.number().optional(),
      pushed_at: z.string().nullable().optional(),
      created_at: z.string().nullable().optional(),
      license: z
        .object({ spdx_id: z.string().nullable().optional() })
        .nullable()
        .optional(),
      topics: z.array(z.string()).default([]),
    }),
    languages: z.record(z.string(), z.number()).default({}),
    contributors: z.array(
      z.object({
        login: z.string(),
        avatar_url: z.string().url().optional(),
        html_url: z.string().url().optional(),
        contributions: z.number(),
      })
    ).default([]),
    issues: z.object({
      open: z.array(ghIssueOrPR).default([]),
      recentlyClosed: z.array(ghIssueOrPR).default([]),
    }),
    pulls: z.object({
      open: z.array(ghIssueOrPR).default([]),
      recentlyMerged: z.array(ghIssueOrPR).default([]),
    }),
    commits: z.array(ghCommit).default([]),
    branches: z.array(ghBranch).default([]),
    releases: z.array(ghRelease).default([]),
    commitActivity: z.array(z.object({
      week: z.number(),
      total: z.number(),
      days: z.array(z.number()).optional(),
    })).default([]),
  }),
});

export const collections = {
  docs: defineCollection({ loader: docsLoader(), schema: docsSchema() }),
  roadmap,
  github,
};
